  "transcript": {
    "segments": [
      {
        "start": 0,
        "end": 1.48,
        "text": "ALT還是新鮮"
      },
      {
        "start": 1.48,
        "end": 2.52,
        "text": "是存在的"
      },
      {
        "start": 2.52,
        "end": 3.52,
        "text": "前陣子呢"
      },
      {
        "start": 3.52,
        "end": 5.28,
        "text": "我用AL幫一個做服裝的朋友"
      },
      {
        "start": 5.28,
        "end": 6.8,
        "text": "搭建了個特別節奏力展"
      },
      {
        "start": 6.8,
        "end": 8.64,
        "text": "但是他給到我的是PRD"
      },
      {
        "start": 8.64,
        "end": 9.96,
        "text": "你還規範這些素材"
      },
      {
        "start": 9.96,
        "end": 11.16,
        "text": "按他以前的做法"
      },
      {
        "start": 11.16,
        "end": 12.56,
        "text": "從領開始搭業面"
      },
      {
        "start": 12.56,
        "end": 13.6,
        "text": "光手頁"
      },
      {
        "start": 13.6,
        "end": 14.64,
        "text": "商品相機頁"
      },
      {
        "start": 14.64,
        "end": 15.96,
        "text": "那幾張核心的頁面"
      },
      {
        "start": 15.96,
        "end": 16.92,
        "text": "沒有兩三天"
      },
      {
        "start": 16.92,
        "end": 18.64,
        "text": "根本做不然能接人的東西"
      },
      {
        "start": 18.64,
        "end": 20.52,
        "text": "但這次我換了個方式"
      },
      {
        "start": 20.52,
        "end": 22.24,
        "text": "我把所有材料就進了true"
      },
      {
        "start": 22.24,
        "end": 23.84,
        "text": "可是他到底能不能幫我"
      },
      {
        "start": 23.84,
        "end": 25.84,
        "text": "從PRD變成可討論demo"
      },
      {
        "start": 25.84,
        "end": 26.72,
        "text": "沒想到"
      },
      {
        "start": 26.72,
        "end": 27.84,
        "text": "還真的能跑通"
      },
      {
        "start": 27.84,
        "end": 28.52,
        "text": "接下來呢"
      },
      {
        "start": 28.52,
        "end": 29.88,
        "text": "取留選擇大家分享一下"
      },
      {
        "start": 29.88,
        "end": 31.04,
        "text": "進入true work"
      },
      {
        "start": 31.04,
        "end": 32.2,
        "text": "先去插件市場"
      },
      {
        "start": 32.2,
        "end": 33.84,
        "text": "先把這三個技能裝上"
      },
      {
        "start": 33.84,
        "end": 35.72,
        "text": "然後再切換到底在模式"
      },
      {
        "start": 35.72,
        "end": 36.52,
        "text": "這個模式呢"
      },
      {
        "start": 36.52,
        "end": 38.2,
        "text": "專門做設計的相關任務"
      },
      {
        "start": 38.2,
        "end": 40.72,
        "text": "人實現從想法到生存的整個流程"
      },
      {
        "start": 40.72,
        "end": 41.76,
        "text": "跟完之後呢"
      },
      {
        "start": 41.76,
        "end": 43.28,
        "text": "如果你有飛根碼鏈接的話"
      },
      {
        "start": 43.28,
        "end": 44.32,
        "text": "直接倒進去就好"
      },
      {
        "start": 44.32,
        "end": 45.36,
        "text": "如果沒有的話"
      },
      {
        "start": 45.36,
        "end": 46.4,
        "text": "可以像我一樣"
      },
      {
        "start": 46.4,
        "end": 47.6,
        "text": "在電話框裡先這樣"
      },
      {
        "start": 47.6,
        "end": 49.04,
        "text": "不然改的來自技能"
      },
      {
        "start": 49.04,
        "end": 51,
        "text": "再把品牌規範全部告訴他"
      },
      {
        "start": 51,
        "end": 52.72,
        "text": "有色碳黑和水泥灰"
      },
      {
        "start": 52.72,
        "end": 54.08,
        "text": "強調色景式成"
      },
      {
        "start": 54.08,
        "end": 54.72,
        "text": "標題呢"
      },
      {
        "start": 54.72,
        "end": 56.44,
        "text": "用蘇武趁線字體"
      },
      {
        "start": 56.44,
        "end": 59.36,
        "text": "則按鈕呢"
      },
      {
        "start": 59.36,
        "end": 60.6,
        "text": "這相當於區域和線學會的"
      },
      {
        "start": 60.6,
        "end": 62.36,
        "text": "咱家的品牌視覺語言"
      },
      {
        "start": 62.36,
        "end": 63.36,
        "text": "後面生存東西呢"
      },
      {
        "start": 63.36,
        "end": 64.36,
        "text": "才不會跑偏"
      },
      {
        "start": 64.36,
        "end": 65.04,
        "text": "這一步呢"
      },
      {
        "start": 65.04,
        "end": 66.44,
        "text": "我今天每個設計時候做"
      },
      {
        "start": 66.44,
        "end": 68.16,
        "text": "不要成功買prime開始生存"
      },
      {
        "start": 68.16,
        "end": 70.4,
        "text": "一定要先讓AI力間比較平台規範"
      },
      {
        "start": 70.4,
        "end": 71.6,
        "text": "規範建立之後"
      },
      {
        "start": 71.6,
        "end": 73.03999999999999,
        "text": "接下來就讓他幹活了"
      },
      {
        "start": 73.03999999999999,
        "end": 74.88,
        "text": "我今天要同一個對話裡數需求"
      },
      {
        "start": 74.88,
        "end": 76.12,
        "text": "再再用這個技能"
      },
      {
        "start": 76.12,
        "end": 77.24,
        "text": "這個技能的好處呢"
      },
      {
        "start": 77.24,
        "end": 78.08,
        "text": "是要生存的界面"
      },
      {
        "start": 78.08,
        "end": 79.44,
        "text": "有明確的視覺風格"
      },
      {
        "start": 79.44,
        "end": 80.48,
        "text": "我會說現在這些界面"
      },
      {
        "start": 80.48,
        "end": 81.88,
        "text": "也率了AI模拔鏈"
      },
      {
        "start": 81.88,
        "end": 83.24,
        "text": "然後我記得補充"
      },
      {
        "start": 83.24,
        "end": 85.12,
        "text": "形怒和關於都要寫出來"
      },
      {
        "start": 85.12,
        "end": 86.32,
        "text": "搜索要難搜"
      },
      {
        "start": 86.32,
        "end": 88.52,
        "text": "上面拘轉是3-4款單品"
      },
      {
        "start": 88.52,
        "end": 90.36,
        "text": "在價格和價格按鈕"
      },
      {
        "start": 90.36,
        "end": 91.4,
        "text": "7-8分鐘左右"
      },
      {
        "start": 91.4,
        "end": 92.64,
        "text": "三個頁面出來了"
      },
      {
        "start": 92.64,
        "end": 94.28,
        "text": "你看這個品牌是用對了"
      },
      {
        "start": 94.28,
        "end": 94.75999999999999,
        "text": "組件呢"
      },
      {
        "start": 94.75999999999999,
        "end": 96.12,
        "text": "用了是我倒了那一套"
      },
      {
        "start": 96.12,
        "end": 96.92,
        "text": "還辦佈局"
      },
      {
        "start": 96.92,
        "end": 99.28,
        "text": "基本符合我成功的prd信息結構"
      },
      {
        "start": 99.28,
        "end": 101,
        "text": "不過我還是想要更嚴僅一點"
      },
      {
        "start": 101,
        "end": 102.47999999999999,
        "text": "於是這樣了這個技能"
      },
      {
        "start": 102.47999999999999,
        "end": 103.32,
        "text": "再輸入指令"
      },
      {
        "start": 103.32,
        "end": 104.84,
        "text": "讓他自己審查一遍"
      },
      {
        "start": 104.84,
        "end": 105.47999999999999,
        "text": "不一會"
      },
      {
        "start": 105.47999999999999,
        "end": 106.88,
        "text": "他真的給了我反饋了"
      },
      {
        "start": 106.88,
        "end": 107.8,
        "text": "有問題的地方"
      },
      {
        "start": 107.8,
        "end": 109.28,
        "text": "誰讓他修復這形拉"
      },
      {
        "start": 109.28,
        "end": 110.47999999999999,
        "text": "全部調整完之後呢"
      },
      {
        "start": 110.47999999999999,
        "end": 111.4,
        "text": "可以先倒出"
      },
      {
        "start": 111.4,
        "end": 113.12,
        "text": "你可以把揮格碼裡面進修"
      },
      {
        "start": 113.12,
        "end": 114.32,
        "text": "或者拉團隊評審"
      },
      {
        "start": 114.32,
        "end": 116.12,
        "text": "還是按你原來的方式進行交付"
      },
      {
        "start": 116.12,
        "end": 117.68,
        "text": "我大概算了一下時間"
      },
      {
        "start": 117.68,
        "end": 118.75999999999999,
        "text": "從建立規範"
      },
      {
        "start": 118.75999999999999,
        "end": 120.6,
        "text": "到場處大概可憑身的頁面"
      },
      {
        "start": 120.6,
        "end": 122.04,
        "text": "總好是補到一小時"
      },
      {
        "start": 122.04,
        "end": 123.72,
        "text": "比傳統方法快了好多"
      },
      {
        "start": 123.72,
        "end": 124.68,
        "text": "真替使用下來"
      },
      {
        "start": 124.68,
        "end": 126.88,
        "text": "我覺得去過很適用來補助搭建筋"
      },
      {
        "start": 126.88,
        "end": 127.64,
        "text": "補方架"
      },
      {
        "start": 127.64,
        "end": 129.4,
        "text": "那剩下很多的時間全本"
      },
      {
        "start": 129.4,
        "end": 130.96,
        "text": "進行安全下來的時間呢"
      },
      {
        "start": 130.96,
        "end": 132.68,
        "text": "你能用來久魔當季的主題"
      },
      {
        "start": 132.68,
        "end": 133.96,
        "text": "和各種視覺趨勢"
      },
      {
        "start": 133.96,
        "end": 134.68,
        "text": "我覺得啦"
      },
      {
        "start": 134.68,
        "end": 136.92000000000002,
        "text": "這才是AI六點設計最有意義的點"
      }
